mapper.select:
select c.inuse_id, a.inuse_contract_id as contract_id, a.contract_name, b.grp_code as grp_code_a, b.hq_grp_code as hq_grp_code_a, b.grp_name as grp_name_a, case when c.relation = '1000' then '使用客户（非收入划转）' when c.relation = '1001' then '使用客户（收入划转）' when c.relation = '1002' then '收入归集客户' end as relation, b2.grp_code as grp_code_b, b2.hq_grp_code as hq_grp_code_b, b2.grp_name as grp_name_b, ifnull(d.user_num, 0) as user_num, date_format(a.contract_effdate, '%Y-%m-%d') as create_time from zqzt_grp_contract_info a left join zqzt_grp_group_info b on a.grp_id = b.grp_id left join zqzt_grp_cust_inuse c on a.inuse_contract_id = c.contract_id and c.is_valid = '1' left join zqzt_grp_group_info b2 on c.grp_id_b = b2.grp_id left join ( select inuse_id, count(1) as user_num from zqzt_grp_cust_inuse_userlist where is_valid = '1' group by inuse_id ) d on c.inuse_id = d.inuse_id
and b.area_id = #{regionId}
and b.county_id = #{countyId}
and b.grp_code = #{grpCodeA}
and b.hq_grp_code = #{hqGrpCodeA}
and a.inuse_contract_id = #{contractId}
and lower(a.contract_name) like lower(concat('%', #{contractName}, '%'))
and b2.grp_code = #{grpCodeB}
and b2.hq_grp_code = #{hqGrpCodeB}
and date_format(a.contract_effdate, '%Y-%m-%d') >= date_format(#{createTimeBegin}, '%Y-%m-%d')
and date_format(a.contract_effdate, '%Y-%m-%d') <= date_format(#{createTimeEnd}, '%Y-%m-%d')
limit #{startIndex}, #{endIndex}

select grp_code as grp_code_b, hq_grp_code as hq_grp_code_b, grp_name as grp_name_b from zqzt_grp_group_info
and grp_code = #{grpCodeB}
and hq_grp_code = #{hqGrpCodeB}
and lower(grp_name) like lower(concat('%', #{grpNameB}, '%'))

select #{inuseId} as INUSE_ID, USER_ID as SUBSCRBID, SVC_NUM, PHYSICAL_CUST_NAME as CUST_NAME from IOB_GOV2.CUST_MAINT_INFO where STATUS = '1' and CUST_ID = #{custId}
and USER_ID not in
#{userId}

select #{inuseId} as INUSE_ID, USER_ID as SUBSCRBID, SVC_NUM, PHYSICAL_CUST_NAME as CUST_NAME from IOB_GOV2.CUST_MAINT_INFO where STATUS = '1'
and USER_ID in
#{userList.subscrbid}

select
    count(1)
from zqzt_grp_contract_info a
left join zqzt_grp_group_info b  on a.grp_id = b.grp_id
left join zqzt_grp_cust_inuse c  on a.inuse_contract_id = c.contract_id and c.is_valid = '1'
left join zqzt_grp_group_info b2 on c.grp_id_b = b2.grp_id
left join (
    select
        inuse_id, count(1) as user_num
    from zqzt_grp_cust_inuse_userlist
    where is_valid = '1'
    group by inuse_id
) d on c.inuse_id = d.inuse_id


        and b.area_id = #{regionId}


        and b.county_id = #{countyId}


        and b.grp_code = #{grpCodeA}


        and b.hq_grp_code = #{hqGrpCodeA}


        and a.inuse_contract_id = #{contractId}


        and lower(a.contract_name) like lower(concat('%', #{contractName}, '%'))


        and b2.grp_code = #{grpCodeB}


        and b2.hq_grp_code = #{hqGrpCodeB}


        and date_format(a.contract_effdate, '%Y-%m-%d') >= date_format(#{createTimeBegin}, '%Y-%m-%d')


        and date_format(a.contract_effdate, '%Y-%m-%d') <= date_format(#{createTimeEnd}, '%Y-%m-%d')
